package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import com.irwi.fincapp.database.DatabaseHelper;import com.irwi.fincapp.session.SessionManager;import com.irwi.fincapp.sync.SyncScheduler;
public class SplashActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=BaseUi.root(this);TextView logo=BaseUi.title(this,"🌱 FincApp");l.addView(logo);l.addView(BaseUi.text(this,"Offline livestock management",22));l.addView(BaseUi.text(this,"Loading secure local database...",18));new DatabaseHelper(this).getWritableDatabase();SyncScheduler.schedule(this);new Handler().postDelayed(()->{Class<?> next=new SessionManager(this).isLogged()?FarmActivity.class:LoginActivity.class;startActivity(new Intent(this,next));finish();},1000);}}
